<script lang="ts">
  import { addRecurringPayment, cancelRecurringPayment, depositToVault, formatCharacterMoney, getCreditScore, getMinimumLoanRate, getHouseholdBudget, setSavingsGoalMonths, issueBankCard, loadPrepaidCard, makeCardPurchase, payCreditCard, repayLoan, setAutoDeposit, takeLoan, withdrawFromVault } from './lib/simulation';
  import type { Character, LoanType, PaymentSourceType, SavingsGoalMonths } from './lib/types';
  import GameChoice from './GameChoice.svelte';
  let { character, onChange, view = 'all' }: { character: Character; onChange: (next: Character) => void; view?: 'all' | 'cards' | 'loans' | 'bills' | 'savings' } = $props();
  let cardType = $state<'debit'|'credit'|'prepaid'>('debit'); let cardName = $state(''); let cardAccount = $state(''); let creditLimit = $state('5000');
  let loanType = $state<LoanType>('personal'); let loanName = $state(''); let loanAmount = $state('10000'); let loanRate = $state('11'); let loanTerm = $state('5'); let loanAccount = $state('');
  let recurringName = $state(''); let recurringAmount = $state('120'); let recurringCategory = $state<'subscription'|'bill'>('subscription'); let recurringSource = $state<PaymentSourceType>('cash'); let recurringSourceId = $state('');
  let depositMethod = $state<'fixed'|'percentage'>('percentage'); let depositValue = $state('10'); let depositAccount = $state('');
  let vaultAmount = $state('100'); let purchaseAmount = $state('100'); let purchaseDescription = $state('Purchase'); let selectedCard = $state(''); let cardPayAmount = $state('100'); let prepaidCardId = $state(''); let prepaidLoadAmount = $state('100'); let selectedLoan = $state(''); let loanPayAmount = $state('100');
  let notice = $state('');
  const accounts = $derived(character.bankAccounts ?? []); const cards = $derived(character.cards ?? []); const loans = $derived((character.loans ?? []).filter((loan)=>loan.active)); const recurring = $derived((character.recurringPayments ?? []).filter((item)=>item.active));
  const householdBudget = $derived(getHouseholdBudget(character));
  const savingsGoalTarget = $derived(character.savingsGoalMonths ? Math.round((householdBudget.total / 12) * character.savingsGoalMonths) : 0);
  function updateSavingsGoal(value: SavingsGoalMonths | null) { onChange(setSavingsGoalMonths(character, value)); }
  const creditScore = $derived(getCreditScore(character)); const minimumLoanRate = $derived(getMinimumLoanRate(character,loanType));
  const creditTier = $derived(creditScore>=750?'Excellent':creditScore>=700?'Good':creditScore>=650?'Fair':creditScore>=600?'Weak':'Poor');
  const creditCards = $derived(cards.filter((card)=>card.type==='credit' && card.active)); const prepaidCards = $derived(cards.filter((card)=>card.type==='prepaid' && card.active)); const paymentCards = $derived(cards.filter((card)=>card.active));
  function n(value:string){const v=Number(value);return Number.isFinite(v)?Math.floor(v):0}
  function run(action:()=>Character,success:string){const next=action();if(next===character){notice='The action could not be completed. Check eligibility, balances, limits and selected accounts.';return;}onChange(next);notice=success;}
  function createCard(){run(()=>issueBankCard(character,cardType,cardName,cardAccount||undefined,n(creditLimit)),'Card issued.');cardName='';}
  function createLoan(){run(()=>takeLoan(character,loanType,loanName,n(loanAmount),Number(loanRate)/100,n(loanTerm),loanAccount||undefined),'Loan issued. Proceeds were added to cash.');loanName='';}
  function createRecurring(){run(()=>addRecurringPayment(character,recurringName,n(recurringAmount),recurringCategory,recurringSource,recurringSourceId||undefined),'Recurring payment saved.');recurringName='';}
  function createAutoDeposit(){run(()=>setAutoDeposit(character,depositAccount,depositMethod,n(depositValue)),'Automatic deposit configured.');}
  function depositVault(){run(()=>depositToVault(character,n(vaultAmount)),'Cash stored in your personal safe.');}
  function withdrawVault(){run(()=>withdrawFromVault(character,n(vaultAmount)),'Cash withdrawn from your personal safe.');}
  function buy(){run(()=>makeCardPurchase(character,selectedCard,n(purchaseAmount),purchaseDescription||'Card purchase'),'Purchase recorded.');}
  function loadPrepaid(){const card=prepaidCards.find((item)=>item.id===prepaidCardId);if(!card)return;run(()=>loadPrepaidCard(character,card.id,n(prepaidLoadAmount)),'Prepaid card loaded.');}
  function payCard(){const card=creditCards.find((item)=>item.id===selectedCard);if(!card)return;run(()=>payCreditCard(character,card.id,n(cardPayAmount),card.linkedAccountId?'account':'cash',card.linkedAccountId),'Card payment completed.');}
  function payLoan(){const loan=loans.find((item)=>item.id===selectedLoan);if(!loan)return;run(()=>repayLoan(character,loan.id,n(loanPayAmount),loan.paymentAccountId?'account':'cash',loan.paymentAccountId),'Loan payment completed.');}
</script>
<section class="products-panel">
  <div class="products-title"><div><small>{view === 'cards' ? 'PAYMENT METHODS' : view === 'loans' ? 'CREDIT SERVICES' : view === 'bills' ? 'RECURRING PAYMENTS' : view === 'savings' ? 'SAVINGS TOOLS' : 'FINANCIAL TOOLS'}</small><h2>{view === 'cards' ? 'Cards' : view === 'loans' ? 'Loans & credit' : view === 'bills' ? 'Bills & subscriptions' : view === 'savings' ? 'Automatic savings & vault' : 'Credit, payments & savings'}</h2></div>{#if view === 'all' || view === 'savings'}<span class="vault-total">Safe · {formatCharacterMoney(character,character.vaultBalance??0)}</span>{/if}</div>
  {#if view === 'all' || view === 'loans'}<div class="credit-score"><div><small>CREDIT SCORE</small><strong>{creditScore}</strong><span>{creditTier}</span></div><p>Payment history, credit-card use, debt and unpaid tax influence your score. Better scores qualify for lower starting loan rates.</p></div>{/if}
  {#if view === 'all' || view === 'cards'}
  <details open={view !== 'all'}><summary>Payment cards <span>{cards.length}/6</span></summary>
    {#each cards as card}<div class="product-row"><div><strong>{card.name}</strong><small>{card.type==='credit'?'Credit · '+formatCharacterMoney(character,card.balance)+' owed / '+formatCharacterMoney(character,card.creditLimit)+' limit':card.type==='prepaid'?'Prepaid · '+formatCharacterMoney(character,card.balance)+' available':'Debit · linked to '+(accounts.find((a)=>a.id===card.linkedAccountId)?.name??'unavailable account')}</small></div><b>{card.type==='credit'?formatCharacterMoney(character,Math.max(0,card.creditLimit-card.balance))+' available':card.type==='prepaid'?formatCharacterMoney(character,card.balance)+' stored':'Active'}</b></div>{/each}
    <div class="form-grid"><div class="choice-field"><span>Card type</span><GameChoice label="Card type" value={cardType} options={[{value:'debit',label:'Debit',detail:'Spend from a bank account'},{value:'credit',label:'Credit',detail:'Borrow within a credit limit'},{value:'prepaid',label:'Prepaid',detail:'Load funds before spending'}]} onSelect={(value) => cardType = value as 'debit'|'credit'|'prepaid'} columns={3}/></div><label>Card name<input bind:value={cardName} placeholder="Everyday card"/></label></div>
    {#if cardType==='debit'}<div class="choice-field"><span>Link bank account</span><GameChoice label="Link bank account" value={cardAccount} options={[{value:'',label:'Choose account'},...accounts.map((a) => ({value:a.id,label:a.name,detail:formatCharacterMoney(character,a.balance)}))]} onSelect={(value) => cardAccount = value} columns={2}/></div>{:else if cardType==='credit'}<div class="form-grid"><label>Credit limit<input type="number" min="1" bind:value={creditLimit}/></label><div class="choice-field"><span>Payment account (optional)</span><GameChoice label="Payment account" value={cardAccount} options={[{value:'',label:'Pay from cash'},...accounts.map((a) => ({value:a.id,label:a.name,detail:formatCharacterMoney(character,a.balance)}))]} onSelect={(value) => cardAccount = value} columns={2}/></div></div><small class="hint">Simplified 18% annual interest. A 5% minimum payment is attempted each year.</small>{:else}<small class="hint">Prepaid cards have no credit line or interest. Load them from cash, then spend only the available balance.</small>{/if}
    <button class="primary" onclick={createCard} disabled={cards.length>=6 || (cardType==='debit' && accounts.length===0)}>Issue card</button>
    {#if cards.length>0}<div class="form-grid"><div class="choice-field"><span>Record purchase with</span><GameChoice label="Purchase card" value={selectedCard} options={[{value:'',label:'Choose card'},...cards.filter((card)=>card.active).map((card) => ({value:card.id,label:card.name,detail:card.type}))]} onSelect={(value) => selectedCard = value} columns={2}/></div><label>Amount<input type="number" min="1" bind:value={purchaseAmount}/></label></div><label>Purchase description<input bind:value={purchaseDescription}/></label><button onclick={buy}>Record card purchase</button>{/if}
    {#if prepaidCards.length>0}<div class="form-grid"><div class="choice-field"><span>Load prepaid card</span><GameChoice label="Prepaid card" value={prepaidCardId} options={[{value:'',label:'Choose prepaid card'},...prepaidCards.map((card) => ({value:card.id,label:card.name,detail:formatCharacterMoney(character,card.balance)}))]} onSelect={(value) => prepaidCardId = value} columns={2}/></div><label>Load amount<input type="number" min="1" bind:value={prepaidLoadAmount}/></label></div><button onclick={loadPrepaid}>Load prepaid card</button>{/if}
    {#if creditCards.length>0}<div class="form-grid"><div class="choice-field"><span>Pay credit card</span><GameChoice label="Credit card to pay" value={selectedCard} options={[{value:'',label:'Choose card'},...creditCards.map((card) => ({value:card.id,label:card.name,detail:formatCharacterMoney(character,card.balance)+' owed'}))]} onSelect={(value) => selectedCard = value} columns={2}/></div><label>Payment amount<input type="number" min="1" bind:value={cardPayAmount}/></label></div><button onclick={payCard}>Pay card balance</button>{/if}
  </details>
  {/if}
  {#if view === 'all' || view === 'loans'}
  <details open={view !== 'all'}><summary>Loans <span>{loans.length}/5 active</span></summary>
    {#each loans as loan}<div class="product-row"><div><strong>{loan.name}</strong><small>{loan.type} · {(loan.annualInterestRate*100).toFixed(1)}% annual · {loan.termYears}-year term</small></div><b>{formatCharacterMoney(character,loan.balance)} owed</b></div>{/each}
    <div class="form-grid"><div class="choice-field"><span>Loan type</span><GameChoice label="Loan type" value={loanType} options={[{value:'personal',label:'Personal',detail:'Individual borrowing'},{value:'mortgage',label:'Mortgage',detail:'Property financing'},{value:'business',label:'Business',detail:'Business capital'}]} onSelect={(value) => loanType = value as LoanType} columns={3}/></div><label>Name<input bind:value={loanName} placeholder="Personal loan"/></label><label>Principal<input type="number" min="1" bind:value={loanAmount}/></label><label>Annual interest %<input type="number" min="0" max="50" step="0.5" bind:value={loanRate}/></label><label>Term (years)<input type="number" min="1" max="30" bind:value={loanTerm}/></label><div class="choice-field"><span>Repayment account</span><GameChoice label="Repayment account" value={loanAccount} options={[{value:'',label:'Use cash'},...accounts.map((a) => ({value:a.id,label:a.name,detail:formatCharacterMoney(character,a.balance)}))]} onSelect={(value) => loanAccount = value} columns={2}/></div></div>
    <small class="hint">Minimum rate for your current score: {(minimumLoanRate*100).toFixed(1)}%. A lower rate is not eligible. Missed payments and high balances can reduce your score.</small>
    <button class="primary" onclick={createLoan} disabled={character.age<18 || loans.length>=5 || creditScore<520 || Number(loanRate)/100<minimumLoanRate}>Take loan</button>
    {#if loans.length>0}<div class="form-grid"><div class="choice-field"><span>Repay loan</span><GameChoice label="Loan to repay" value={selectedLoan} options={[{value:'',label:'Choose loan'},...loans.map((loan) => ({value:loan.id,label:loan.name,detail:formatCharacterMoney(character,loan.balance)+' owed'}))]} onSelect={(value) => selectedLoan = value} columns={2}/></div><label>Repayment amount<input type="number" min="1" bind:value={loanPayAmount}/></label></div><button onclick={payLoan}>Make extra repayment</button>{/if}
    <small class="hint">Annual interest accrues and a simplified principal installment is attempted automatically. Missed installments remain outstanding; interest is not erased.</small>
  </details>
  {/if}
  {#if view === 'all' || view === 'bills'}
  <details open={view !== 'all'}><summary>Subscriptions & recurring bills <span>{recurring.length}/12 active</span></summary>
    {#each recurring as item}<div class="product-row"><div><strong>{item.name}</strong><small>{item.category} · {item.sourceType} · {formatCharacterMoney(character,item.amount)} / year</small></div><button class="quiet" onclick={()=>run(()=>cancelRecurringPayment(character,item.id),'Recurring payment cancelled.')}>Cancel</button></div>{/each}
    <div class="form-grid"><label>Name<input bind:value={recurringName} placeholder="Music subscription"/></label><label>Annual amount<input type="number" min="1" bind:value={recurringAmount}/></label><div class="choice-field"><span>Category</span><GameChoice label="Recurring payment category" value={recurringCategory} options={[{value:'subscription',label:'Subscription',detail:'Optional service or membership'},{value:'bill',label:'Recurring bill',detail:'Regular household expense'}]} onSelect={(value) => recurringCategory = value as 'subscription'|'bill'} columns={2} compact/></div><div class="choice-field"><span>Payment source</span><GameChoice label="Recurring payment source" value={recurringSource} options={[{value:'cash',label:'Cash'},{value:'account',label:'Bank account'},{value:'card',label:'Payment card'}]} onSelect={(value) => { recurringSource = value as PaymentSourceType; recurringSourceId = ''; }} columns={3} compact/></div></div>
    {#if recurringSource==='account'}<div class="choice-field"><span>Account</span><GameChoice label="Recurring payment account" value={recurringSourceId} options={[{value:'',label:'Choose account'},...accounts.map((a) => ({value:a.id,label:a.name,detail:formatCharacterMoney(character,a.balance)}))]} onSelect={(value) => recurringSourceId = value} columns={2}/></div>{:else if recurringSource==='card'}<div class="choice-field"><span>Payment card</span><GameChoice label="Recurring payment card" value={recurringSourceId} options={[{value:'',label:'Choose card'},...paymentCards.map((card) => ({value:card.id,label:card.name,detail:card.type}))]} onSelect={(value) => recurringSourceId = value} columns={2}/></div>{/if}
    <button class="primary" onclick={createRecurring} disabled={recurring.length>=12}>Add recurring payment</button><small class="hint">Charges run once per simulated year. Failed cash/account charges are logged as missed and do not create debt. Credit cards use available credit; prepaid cards use their loaded balance.</small>
  </details>
  {/if}
  {#if view === 'all' || view === 'savings'}
  <details open={view !== 'all'}><summary>Automatic savings deposits</summary>
    <div class="form-grid"><div class="choice-field"><span>Destination account</span><GameChoice label="Savings destination" value={depositAccount} options={[{value:'',label:'Choose account'},...accounts.map((a) => ({value:a.id,label:a.name,detail:formatCharacterMoney(character,a.balance)}))]} onSelect={(value) => depositAccount = value} columns={2}/></div><div class="choice-field"><span>Deposit method</span><GameChoice label="Automatic savings method" value={depositMethod} options={[{value:'percentage',label:'Percentage',detail:'Save a share of income'},{value:'fixed',label:'Fixed amount',detail:'Save a set amount each year'}]} onSelect={(value) => depositMethod = value as 'fixed'|'percentage'} columns={2}/></div><label>{depositMethod==='percentage'?'Percentage (1–90)':'Amount per year'}<input type="number" min="1" max={depositMethod==='percentage'?90:100000000} bind:value={depositValue}/></label></div>
    <button class="primary" onclick={createAutoDeposit} disabled={!depositAccount}>Save automatic deposit</button><small class="hint">Applied after annual income and household expenses, only when cash is sufficient.</small>
  </details>
  <details open={view !== 'all'}><summary>Emergency savings target</summary>
    <p class="hint">Set a target based on one, three, or six months of estimated living costs.</p>
    <div class="action-row">
      {#each [1,3,6] as months}
        <button class:goal-active={character.savingsGoalMonths===months} disabled={character.age<18} onclick={() => updateSavingsGoal(months as SavingsGoalMonths)}>{months} month{months===1?'':'s'}</button>
      {/each}
    </div>
    <button class="quiet" disabled={character.age<18} onclick={() => updateSavingsGoal(null)}>No savings target</button>
    {#if character.age<18}<small class="hint">Emergency savings targets unlock at age 18.</small>{/if}
    {#if character.savingsGoalMonths}
      <div class="vault-balance"><small>TARGET · {character.savingsGoalMonths} MONTHS</small><strong>{formatCharacterMoney(character,savingsGoalTarget)}</strong><small>Cash balance · {formatCharacterMoney(character)}</small></div>
      <div class="savings-progress"><span style="width:{Math.min(100,Math.round(character.money/Math.max(1,savingsGoalTarget)*100))}%"></span></div>
      <small class="hint">{Math.min(100,Math.round(character.money/Math.max(1,savingsGoalTarget)*100))}% of your target.</small>
    {/if}
  </details>
  <details open={view !== 'all'}><summary>Personal safe / vault</summary>
    <div class="vault-balance"><small>STORED SECURELY</small><strong>{formatCharacterMoney(character,character.vaultBalance??0)}</strong></div>
    <label>Amount<input type="number" min="1" bind:value={vaultAmount}/></label><div class="action-row"><button onclick={depositVault}>Store cash</button><button onclick={withdrawVault}>Withdraw cash</button></div><small class="hint">The safe holds physical cash. It earns no interest and is included in net worth.</small>
  </details>
  {/if}
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
</section>
<style>
.products-panel{border:1px solid color-mix(in srgb,var(--line-strong) 9%, transparent);border-radius:16px;padding:16px;margin:16px 0;background:color-mix(in srgb,var(--surface-raised) 2%, transparent)}.credit-score{display:flex;align-items:center;gap:12px;padding:10px;margin:10px 0;border-radius:10px;background:color-mix(in srgb,var(--surface-raised) 4%, transparent)}.credit-score>div{min-width:76px}.credit-score small,.credit-score span{display:block;color:var(--muted,var(--muted));font-size:9px}.credit-score strong{display:block;font-size:21px;margin:2px 0}.credit-score p{font-size:10px;line-height:1.45;color:var(--muted,var(--muted));margin:0}.products-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:8px}.products-title small,.vault-total,.hint,.product-row small,.vault-balance small{color:var(--muted,var(--muted));font-size:11px}.products-title h2{font-size:17px;margin:3px 0}.products-panel details{border-top:1px solid color-mix(in srgb,var(--line-strong) 8%, transparent);padding:12px 0}.products-panel summary{cursor:pointer;font-size:13px;font-weight:700;display:flex;justify-content:space-between}.products-panel summary span{color:var(--muted,var(--muted));font-weight:500}.product-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid color-mix(in srgb,var(--line-strong) 5%, transparent)}.product-row strong,.product-row small{display:block}.product-row strong{font-size:12px}.product-row small{margin-top:3px}.product-row b{font-size:12px;white-space:nowrap}.choice-field{display:grid;gap:5px;margin:8px 0;color:var(--muted);font-size:11px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}label{display:grid;gap:5px;margin:9px 0;color:var(--muted,var(--muted));font-size:11px}input,select{width:100%;min-width:0;padding:10px;border:1px solid color-mix(in srgb,var(--line-strong) 13%, transparent);border-radius:8px;background:var(--surface);color:var(--text);font:inherit;font-size:12px}.products-panel button{padding:9px 12px;border-radius:8px;border:1px solid color-mix(in srgb,var(--line-strong) 13%, transparent);background:color-mix(in srgb,var(--surface-raised) 6%, transparent);color:inherit;font-size:11px;font-weight:650}.products-panel button.primary{background:var(--accent,var(--accent-strong));color:var(--on-accent);border:0}.products-panel button.quiet{padding:5px 8px}.action-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.vault-balance{padding:12px;border-radius:10px;background:color-mix(in srgb,var(--surface-raised) 3.5%, transparent)}.vault-balance strong{display:block;font-size:17px;margin-top:4px}.goal-active{border-color:var(--accent,var(--accent))!important;color:var(--accent,var(--accent))!important;background:color-mix(in srgb,var(--accent-strong) 10%, transparent)!important}.savings-progress{height:7px;margin-top:9px;border-radius:9px;background:color-mix(in srgb,var(--surface-raised) 8%, transparent);overflow:hidden}.savings-progress span{display:block;height:100%;border-radius:inherit;background:var(--accent,var(--accent-strong))}.hint{display:block;line-height:1.5;margin:8px 0}.notice{font-size:12px;color:var(--accent,var(--accent))}@media(max-width:460px){.products-panel{padding:12px}.form-grid{grid-template-columns:1fr}.products-title{align-items:flex-start;flex-direction:column}}
</style>